<script setup>
import { onMounted, ref } from 'vue'
import api, { kyat, errorText } from '../api'
const orders=ref([]),selected=ref(null),error=ref(''),message=ref(''),filter=ref(''),method=ref('cash'),busy=ref(false)
const next={pending:['preparing','cancelled'],preparing:['served','cancelled'],served:['completed','cancelled'],completed:[],cancelled:[]}
async function load(){try{orders.value=(await api.get('/api/orders',{params:filter.value?{status:filter.value}:{}})).data;if(selected.value){const found=orders.value.find(o=>o.id===selected.value.id);if(!found)selected.value=null}}catch(e){error.value=errorText(e)}}
async function show(id){error.value='';try{selected.value=(await api.get(`/api/orders/${id}`)).data}catch(e){error.value=errorText(e)}}
onMounted(load)
async function status(s){if(s==='cancelled'&&!confirm('Cancel order and restore tracked stock?'))return;busy.value=true;error.value='';message.value='';try{selected.value=(await api.patch(`/api/orders/${selected.value.id}/status`,{status:s})).data;message.value='Status updated.';await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function pay(){if(!confirm(`Record full payment of ${kyat(selected.value.total_amount)} via ${method.value}?`))return;busy.value=true;error.value='';message.value='';try{selected.value=(await api.post(`/api/orders/${selected.value.id}/pay`,{method:method.value})).data;message.value='Payment recorded.';await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template>
  <div v-if="error" class="alert alert-danger">{{ error }}</div><div v-if="message" class="alert alert-success">{{ message }}</div>
  <div class="d-flex justify-content-between align-items-center mb-3"><div class="filter-row mb-0"><div><label class="field-label">Order status</label><select v-model="filter" class="form-select" @change="load"><option value="">All statuses</option><option v-for="s in ['pending','preparing','served','completed','cancelled']" :key="s">{{ s }}</option></select></div></div><router-link to="/orders/new" class="btn btn-primary">＋ New order</router-link></div>
  <div class="split-layout"><div class="panel"><div class="panel-header"><h3>Latest orders</h3><button class="btn btn-sm btn-outline-secondary" @click="load">Refresh</button></div><div class="order-list"><button v-for="o in orders" :key="o.id" :class="{selected:selected?.id===o.id}" @click="show(o.id)"><strong>{{ o.order_number }}</strong><span class="d-flex justify-content-between mt-2"><small>{{ o.table?.name||'Takeaway' }} · {{ o.status }}</small><b style="font-size:12px">{{ kyat(o.total_amount) }}</b></span><small>{{ o.payment ? '✓ Paid' : 'Unpaid' }}</small></button><div v-if="!orders.length" class="empty-state">No orders match this filter.</div></div></div>
    <div class="panel"><template v-if="selected"><div class="panel-header"><h3>Order details</h3><span class="status-pill">{{ selected.status }}</span></div><div class="mb-3"><strong>{{ selected.order_number }}</strong><p class="muted mb-0 mt-1" style="font-size:12px">{{ selected.table?.name||'Takeaway' }} · Created by {{ selected.user?.name }}</p></div><div class="cart-line" v-for="line in selected.items" :key="line.id"><div><strong>{{ line.product_name }}</strong><small>Qty {{ line.qty }} · {{ kyat(line.unit_price) }} each</small></div><strong>{{ kyat(line.subtotal) }}</strong></div><p v-if="selected.notes" class="muted small mt-3">Notes: {{ selected.notes }}</p><div class="order-summary"><span>Total</span><strong>{{ kyat(selected.total_amount) }}</strong></div><div class="mb-3"><label class="field-label">Order progress</label><div class="small-actions"><button v-for="s in next[selected.status]" :key="s" class="btn" :class="s==='cancelled'?'btn-outline-danger':'btn-outline-primary'" :disabled="busy||(s==='cancelled'&&!!selected.payment)" @click="status(s)">{{ s==='cancelled'?'Cancel order':'Mark '+s }}</button></div></div><hr/><div v-if="selected.payment"><span class="badge-available">✓ Paid — {{ selected.payment.method }}</span><div class="muted mt-2 small">{{ selected.payment.paid_at }}</div></div><div v-else-if="selected.status!=='cancelled'"><label class="field-label">Payment method</label><select v-model="method" class="form-select mb-2"><option value="cash">Cash</option><option value="kbzpay">KBZPay</option><option value="wavepay">WavePay</option><option value="card">Card</option></select><button class="btn btn-primary w-100" :disabled="busy" @click="pay">Record full payment — {{ kyat(selected.total_amount) }}</button></div><p v-else class="muted small">Cancelled order — no payment accepted.</p></template><div v-else class="empty-state">Select an order on the left to view details.</div></div>
  </div>
</template>
